entries[82747] = { ["name"] = "Die Axt der irdischen Trennung", ["text"] = "40 Meter Reichweite\nSofort\nSchleudert die Axt auf einen Smaragdkoloss, um ihn zu spalten und sehr zu schwächen. Die Axt wird zu Euch zurückkehren. Reichweite 40 Meter." }
entries[82748] = { ["name"] = "Beißwut", ["text"] = "Wenn Ihr mit Eurer Fähigkeit 'Fass!' zwei Mal hintereinander einen kritischen Treffer erzielt, wird die dritte Anwendung 10% mehr Schaden verursachen und die Fokuskosten werden um 5 verringert." }
