entries[82755] = { ["name"] = "Schattengeschoss", ["text"] = "Unbegrenzte Reichweite\nSofort\nFeuert ein Geschoss auf ein zufälliges Ziel ab. Wenn das Geschoss auftrifft, fügt es allen Gegnern im Umkreis von 5 Metern um dieses Gebiet Schattenschaden zu." }
entries[82756] = { ["name"] = "Schattengeschoss", ["text"] = "10 - 70 Meter Reichweite\nWirken in 1 sek.\nFeuert ein Geschoss auf ein zufälliges Ziel ab. Wenn das Geschoss auftrifft, fügt es allen Gegnern im Umkreis von 5 Metern um dieses Gebiet Schattenschaden zu." }
