entries[82762] = { ["name"] = "Wasserdurchtränkt", ["text"] = "100 Meter Reichweite\nSofort\nDurchnässt einen Feind mit eisigem Wasser und reduziert sein Bewegungstempo um 25%. Während sie durchnässt sind, sind Feinde gegen bestimmte Frostattacken empfindlich. Sich einer Flamme auszusetzen kann diesen Effekt entfernen." }
